// === Tab: shader ===
var vert = `

//standard vertex shader
		#ifdef GL_ES
      precision highp float;
    #endif
		#extension GL_OES_standard_derivatives : enable

    // attributes, in
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    attribute vec2 aTexCoord;
    attribute vec4 aVertexColor;

    // attributes, out
    varying vec3 var_vertPos;
    varying vec4 var_vertCol;
    varying vec3 var_vertNormal;
    varying vec2 var_vertTexCoord;

    // matrices
    uniform mat4 uModelViewMatrix;
    uniform mat4 uProjectionMatrix;
    uniform mat3 uNormalMatrix;

		//
		uniform float u_time;

    void main() {
      vec3 pos = aPosition;  
      pos.xz += (sin(u_time + 3.14*aTexCoord.y*2.) + sin(u_time*.76 + 3.14*aTexCoord.y*0.1))*0.25 * pos.xz;
			pos.y += sin(u_time/2.)*.5;
      gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(pos, 1.0);

      // set out value
      var_vertPos      = pos;
      var_vertCol      = aVertexColor;
      var_vertNormal   = aNormal;
      var_vertTexCoord = aTexCoord;
    }
`;


var frag = `

#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform vec2 u_mouse;
#define PI 3.14159265359

//attributes, in
varying vec2 var_vertTexCoord;
varying vec3 var_vertNormal;



vec3 lightDir = vec3(0.5,-1.0,1.0);

void main(){
    vec2 p = gl_FragCoord.xy/u_resolution;
    float ramb = dot(var_vertNormal,lightDir);
    ramb = (ramb +1.0) * .5;
    gl_FragColor = vec4(vec3(1.-ramb)*vec3(0.,0.1,0.4) + vec3(ramb) * vec3(0.8,0.9,1.0) ,1.0);
}

`;

